import { readFile, writeFile } from "node:fs/promises";
import { dirname, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const entry = resolve(root, "scripts/main.mjs");
const output = resolve(root, "main.mjs");

const modules = new Map();

await loadModule(entry);
const ordered = topologicalOrder(entry);
const chunks = [
  "// Generated by tools/bundle-runtime.mjs. Do not edit this file directly.",
  "// Hunter's Bestiary - D&D 5e 2024 uses a single Foundry entry module so settings", 
  "// registration and the public API cannot be lost to partial nested-module loading.",
  "const __hbModules = Object.create(null);",
  ""
];

for (const id of ordered) chunks.push(transformModule(modules.get(id)));
chunks.push("");
await writeFile(output, `${chunks.join("\n")}\n`);
console.log(`Bundled ${ordered.length} runtime modules into ${relative(root, output)}`);

async function loadModule(id) {
  if (modules.has(id)) return;
  const source = await readFile(id, "utf8");
  const imports = parseImports(source, id);
  modules.set(id, { id, source, imports });
  for (const dependency of imports.map(item => item.resolved)) await loadModule(dependency);
}

function parseImports(source, importer) {
  const imports = [];
  const pattern = /^import\s*\{([\s\S]*?)\}\s*from\s*["']([^"']+)["'];?\s*$/gm;
  for (const match of source.matchAll(pattern)) {
    const specifier = match[2];
    if (!specifier.startsWith(".")) throw new Error(`Unsupported non-relative import '${specifier}' in ${relative(root, importer)}`);
    const resolved = resolve(dirname(importer), specifier);
    const bindings = match[1].split(",").map(value => value.trim()).filter(Boolean).map(value => {
      const alias = value.split(/\s+as\s+/);
      return { imported: alias[0].trim(), local: (alias[1] ?? alias[0]).trim() };
    });
    imports.push({ statement: match[0], specifier, resolved, bindings });
  }
  const stripped = source.replace(pattern, "");
  if (/^\s*import\b/m.test(stripped)) throw new Error(`Unsupported import syntax in ${relative(root, importer)}`);
  return imports;
}

function topologicalOrder(entryId) {
  const visited = new Set();
  const visiting = new Set();
  const ordered = [];
  const visit = id => {
    if (visited.has(id)) return;
    if (visiting.has(id)) throw new Error(`Circular runtime dependency at ${relative(root, id)}`);
    visiting.add(id);
    for (const dependency of modules.get(id).imports.map(item => item.resolved)) visit(dependency);
    visiting.delete(id);
    visited.add(id);
    ordered.push(id);
  };
  visit(entryId);
  return ordered;
}

function transformModule(module) {
  let source = module.source;
  const importLines = [];
  for (const item of module.imports) {
    source = source.replace(item.statement, "");
    const moduleKey = keyFor(item.resolved);
    const bindings = item.bindings.map(({ imported, local }) => imported === local ? imported : `${imported}: ${local}`).join(", ");
    importLines.push(`  const { ${bindings} } = __hbModules[${JSON.stringify(moduleKey)}];`);
  }

  const exports = new Set();
  source = source.replace(/^export\s+(?=(?:async\s+)?function\s+|class\s+|(?:const|let|var)\s+)/gm, "");
  for (const pattern of [
    /^(?:async\s+)?function\s+([A-Za-z_$][\w$]*)/gm,
    /^class\s+([A-Za-z_$][\w$]*)/gm,
    /^(?:const|let|var)\s+([A-Za-z_$][\w$]*)/gm
  ]) {
    for (const match of module.source.matchAll(new RegExp(`^export\\s+${pattern.source.slice(1)}`, pattern.flags))) exports.add(match[1]);
  }
  source = source.replace(/^export\s*\{([^}]+)\};?\s*$/gm, (_match, names) => {
    for (const value of names.split(",").map(entry => entry.trim()).filter(Boolean)) {
      const parts = value.split(/\s+as\s+/);
      exports.add((parts[1] ?? parts[0]).trim());
    }
    return "";
  });
  if (/^\s*export\b/m.test(source)) throw new Error(`Unsupported export syntax in ${relative(root, module.id)}`);

  const returnLine = exports.size ? `  return { ${[...exports].join(", ")} };` : "  return Object.freeze({});";
  const body = source.trim().split("\n").map(line => `  ${line}`).join("\n");
  return [
    `__hbModules[${JSON.stringify(keyFor(module.id))}] = (() => {`,
    ...importLines,
    body,
    returnLine,
    "})();",
    ""
  ].join("\n");
}

function keyFor(id) {
  return relative(root, id).replaceAll("\\", "/");
}
